// DecodeExportChecklistRequest returns a decoder for requests sent to the
// oktaResourceConnections exportChecklist endpoint.
func DecodeExportChecklistRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*oktaresourceconnections.ExportChecklistPayload, error) {
	return func(r *http.Request) (*oktaresourceconnections.ExportChecklistPayload, error) {
		var payload *oktaresourceconnections.ExportChecklistPayload
		var (
			format       string
			includeAll   bool
			sessionToken *string
			err          error
		)
		qp := r.URL.Query()
		formatRaw := qp.Get("format")
		if formatRaw != "" {
			format = formatRaw
		} else {
			format = "csv"
		}
		if !(format == "csv" || format == "markdown") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("format", format, []any{"csv", "markdown"}))
		}
		{
			includeAllRaw := qp.Get("include_all")
			if includeAllRaw != "" {
				v, err2 := strconv.ParseBool(includeAllRaw)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("include_all", includeAllRaw, "boolean"))
				}
				includeAll = v
			}
		}
		sessionTokenRaw := r.Header.Get("Gram-Session")
		if sessionTokenRaw != "" {
			sessionToken = &sessionTokenRaw
		}
		if err != nil {
			return payload, err
		}
		payload = NewExportChecklistPayload(format, includeAll, sessionToken)
		if payload.SessionToken != nil {
			if strings.Contains(*payload.SessionToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.SessionToken, " ", 2)[1]
				payload.SessionToken = &cred
			}
		}

		return payload, nil
	}
}

